using DigitalEvidenceSystem.Web.Data; using DigitalEvidenceSystem.Web.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace DigitalEvidenceSystem.Web.Pages.Custody; [Authorize] public sealed class IndexModel(EvidenceDbContext db):PageModel { public List<CustodyRecord> Items{get;set;}=[]; public async Task OnGetAsync()=>Items=await db.CustodyRecords.Include(x=>x.EvidenceItem).OrderByDescending(x=>x.TransferredAt).ToListAsync();}
